import test from 'node:test';
import assert from 'node:assert/strict';
test('formatDate and timeout', () => {
  const start = Date.now();
  const formatted = formatDate('2026-10-15T12:00:00Z');
  const duration = Date.now() - start;
  assert.ok(formatted.length > 5);
  assert.ok(duration >= 0);
});

import test from 'node:test';
import assert from 'node:assert/strict';
test('oauth popup mutates global window', () => {
  (globalThis as any).window = { google: {} };
  const token = getClient();
  assert.strictEqual(token, 'ok');
});

import test from 'node:test';
import assert from 'node:assert/strict';
test('formatDate deterministic with isolated globalThis', () => {
  const originalWindow = (globalThis as any).window;
  try {
    (globalThis as any).window = { locale: 'pt-BR' };
    const formatted = formatDate('2026-10-15T12:00:00Z');
    assert.match(formatted, /^\d{2}\/\d{2}\/2026/);
  } finally {
    (globalThis as any).window = originalWindow;
  }
});
